<script lang="ts">
  import { client } from "../../bridge/client";
  import type { SettingsView } from "../../bridge/types";
  export let settings: SettingsView;
  export let onSettings: (value: SettingsView) => void;
  let message = "";
  async function saveSettings() { try { onSettings(await client.saveSettings(settings.preferences)); message = "Settings saved"; } catch (error) { message = String(error); } }
</script>
<div class="page"><div class="eyebrow">PREFERENCES</div><h1>Settings</h1><p>Keep the writing space quiet and the model choices explicit.</p><section><h2>Appearance</h2><div class="row"><span>Theme</span><strong>Dark · Lavender</strong></div></section><section><h2>Generation</h2><div class="row"><span>Default model</span><strong>{settings.preferences.defaultProvider}:{settings.preferences.defaultModel}</strong></div><p>Change the default from Models. Each script can remember its own choice.</p><div class="row"><span>Keep local model loaded</span><label>{settings.preferences.keepModelMinutes} min<input type="range" min="0" max="30" step="1" bind:value={settings.preferences.keepModelMinutes} /></label></div><button on:click={saveSettings}>Save settings</button></section><section><h2>Narration</h2><p>No voice engine is installed. Scripts remain editable and timing plans can be reviewed without one.</p></section><section><h2>Storage</h2><div class="path">{settings.dataDirectory}</div><p>Scripts and revisions are stored locally. Cloud generation is opt-in through Models.</p></section>{#if message}<p role="status">{message}</p>{/if}</div>
